import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
  } = THREE;

  const root = new Group();
  const resources = [];
  const cleanupCallbacks = [];

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const makeBasic = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    resources.push(material);
    return material;
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = makeBasic({ color: colors.surface });
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.043, 0.043, 0.055),
      smoothstep(0.1, 0.9, uv().x),
    ),
    smoothstep(0.0, 1.0, uv().y),
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 2.85, -2.5);
  root.add(backdrop);

  const panelGeometry = new PlaneGeometry(2.8, 1.05);
  const panelMaterial = makeBasic({ color: colors.ink });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.position.set(0, 0, -0.08);
  root.add(panel);

  const imageGeometry = new PlaneGeometry(2.56, 0.81);
  const imageMaterial = makeBasic({
    color: colors.paper,
    transparent: true,
    opacity: 0.96,
    depthWrite: false,
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.position.set(0, 0.04, 0.03);
  root.add(imagePlane);

  const topRailGeometry = new BoxGeometry(2.88, 0.045, 0.055);
  const topRailMaterial = makeBasic({ color: colors.paper });
  const topRail = new Mesh(topRailGeometry, topRailMaterial);
  topRail.position.set(0, 0.555, 0.08);
  root.add(topRail);

  const bottomRailGeometry = new BoxGeometry(2.88, 0.045, 0.055);
  const bottomRailMaterial = makeBasic({ color: colors.paper });
  const bottomRail = new Mesh(bottomRailGeometry, bottomRailMaterial);
  bottomRail.position.set(0, -0.555, 0.08);
  root.add(bottomRail);

  const accentGeometry = new BoxGeometry(0.085, 0.78, 0.075);
  const accentMaterial = makeBasic({ color: colors.accent });
  const accentRail = new Mesh(accentGeometry, accentMaterial);
  accentRail.position.set(-1.405, 0.02, 0.12);
  root.add(accentRail);

  const cornerGeometry = new BoxGeometry(0.34, 0.045, 0.075);
  const cornerMaterial = makeBasic({ color: colors.accent });
  const cornerMark = new Mesh(cornerGeometry, cornerMaterial);
  cornerMark.position.set(1.23, -0.37, 0.12);
  root.add(cornerMark);

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((texture) => {
        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  const primitives = [];
  for (const primitive of config.cinematicPrimitives ?? []) {
    const factory = ctx.primitives?.[primitive.name];
    if (typeof factory === 'function') {
      const result = factory(root, primitive.params);
      if (result?.cleanup) primitives.push(result);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const primitive of primitives) {
      primitive.cleanup();
    }
    for (const callback of cleanupCallbacks) {
      callback();
    }
    for (const child of root.children) {
      if (child.geometry?.dispose) child.geometry.dispose();
    }
    for (const material of resources) {
      material.dispose?.();
    }
  };

  return root;
}
